            starter: "#include <iostream>\n\nclass IntArray {\npublic:\n    void pushBack(int v) { data[count++] = v; }\n    int at(int i) const { return data[i]; }\n    int size() const { return count; }\n    void removeLast() { count--; }\n    void clear() { count = 0; }\nprivate:\n    int data[100]{};\n    int count{0};\n};\n\nclass Stack : public IntArray {\npublic:\n    void push(int v) { pushBack(v); }\n    int pop() {\n        int v = at(size() - 1);\n        removeLast();\n        return v;\n    }\n    bool empty() const { return size() == 0; }\n};\n\nint main() {\n    Stack s;\n    char cmd;\n    while (std::cin >> cmd && cmd != 'q') {\n        if (cmd == 'p') {\n            int v;\n            std::cin >> v;\n            s.push(v);\n        } else if (cmd == 'o') {\n            if (s.empty()) std::cout << \"ว่าง\\n\";\n            else std::cout << s.pop() << \"\\n\";\n        } else if (cmd == 's') {\n            std::cout << \"ขนาด: \" << s.size() << \"\\n\";\n        }\n    }\n    return 0;\n}\n", xp: 70,
