            starter: "#include <iostream>\n#include <queue>\n\nint main() {\n    int n;\n    std::cin >> n;\n    std::priority_queue<int> pq;\n    // อ่านคะแนนใส่ pq แล้วอ่าน k\n    return 0;\n}\n", xp: 60,
