            goal: "input: n ตามด้วยตัวเลข n ตัว · <code>Samples b(std::move(a));</code> · แสดง <b>a: 0 ตัว</b> และ <b>b: n ตัว (ผลรวม S)</b>",
            starter: "#include <iostream>\n#include <utility>\n\nclass Samples {\npublic:\n    explicit Samples(int n) : size{n}, data{new int[n]{}} {}\n    Samples(Samples&& other) noexcept {\n        // ขโมยทรัพยากรจาก other แล้วทำให้ other ว่าง\n    }\n    Samples(const Samples&) = delete;\n    Samples& operator=(const Samples&) = delete;\n    ~Samples() { delete[] data; }\n    int& at(int i) { return data[i]; }\n    int count() const { return size; }\n    long long sum() const {\n        long long s = 0;\n        for (int i = 0; i < size; i++) s += data[i];\n        return s;\n    }\nprivate:\n    int size{0};\n    int* data{nullptr};\n};\n\nint main() {\n    int n;\n    std::cin >> n;\n    Samples a(n);\n    for (int i = 0; i < n; i++) std::cin >> a.at(i);\n    Samples b(std::move(a));\n    std::cout << \"a: \" << a.count() << \" ตัว\\n\";\n    std::cout << \"b: \" << b.count() << \" ตัว (ผลรวม \" << b.sum() << \")\\n\";\n    return 0;\n}\n", xp: 70,
