            starter: "#include <iostream>\n#include <iomanip>\n#include <string>\n\n// เขียน template maxOf ตรงนี้\n\nint main() {\n    int k;\n    std::cin >> k;\n    std::cout << std::fixed << std::setprecision(2);\n    // อ่านชนิดและค่า แล้วเรียก maxOf\n    return 0;\n}\n", xp: 50,
