            goal: "input: คำสั่งจนเจอ <code>q</code> · <code>put k v</code> เก็บ (คีย์ซ้ำให้ค่าใหม่ทับ) · <code>get k</code> แสดงค่า หรือ <b>ไม่พบ k</b>",
            starter: "#include <iostream>\n#include <string>\n#include <utility>\n#include <vector>\n\nclass HashTable {\npublic:\n    void put(int key, const std::string& value) {\n        auto& bucket = buckets[indexOf(key)];\n        for (auto& entry : bucket) {\n            if (entry.first == key) { entry.second = value; return; }\n        }\n        bucket.push_back({key, value});\n    }\n    const std::string* get(int key) const {\n        for (const auto& entry : buckets[indexOf(key)]) {\n            if (entry.first == key) return &entry.second;\n        }\n        return nullptr;\n    }\nprivate:\n    static constexpr int SIZE = 7;\n    std::vector<std::vector<std::pair<int, std::string>>> buckets = std::vector<std::vector<std::pair<int, std::string>>>(SIZE);\n    int indexOf(int key) const { return key % SIZE; }\n};\n\nint main() {\n    HashTable table;\n    std::string cmd;\n    while (std::cin >> cmd && cmd != \"q\") {\n        int key;\n        std::cin >> key;\n        if (cmd == \"put\") {\n            std::string v;\n            std::cin >> v;\n            table.put(key, v);\n        } else if (const std::string* v = table.get(key)) {\n            std::cout << *v << \"\\n\";\n        } else {\n            std::cout << \"ไม่พบ \" << key << \"\\n\";\n        }\n    }\n    return 0;\n}\n", xp: 60,
