            starter: "#include <iostream>\n#include <vector>\n\n// เขียนฟังก์ชัน backtracking วางราชินีทีละแถว\n\nint main() {\n    int n;\n    std::cin >> n;\n    // นับจำนวนวิธี และจำวิธีแรกที่พบ\n    return 0;\n}\n", xp: 130,
