            starter: "#include <iostream>\n#include <mutex>\n#include <string>\n\nstruct Account {\n    std::string name;\n    long long balance{0};\n    std::mutex m;\n};\n\nbool transfer(Account& from, Account& to, long long amount) {\n    std::lock_guard<std::mutex> lockFrom(from.m);\n    std::lock_guard<std::mutex> lockTo(to.m);\n    if (from.balance < amount) return false;\n    from.balance -= amount;\n    to.balance += amount;\n    return true;\n}\n\nint main() {\n    Account a, b;\n    a.name = \"a\";\n    b.name = \"b\";\n    std::cin >> a.balance >> b.balance;\n    char cmd;\n    while (std::cin >> cmd && cmd != 'q') {\n        if (cmd == 's') {\n            std::cout << \"a: \" << a.balance << \" · b: \" << b.balance << \"\\n\";\n            continue;\n        }\n        std::string f, t;\n        long long amount;\n        std::cin >> f >> t >> amount;\n        Account& from = (f == \"a\") ? a : b;\n        Account& to = (t == \"a\") ? a : b;\n        if (&from == &to) {\n            std::cout << \"โอนให้บัญชีเดียวกันไม่ได้\\n\";\n        } else if (transfer(from, to, amount)) {\n            std::cout << \"โอน \" << amount << \" จาก \" << f << \" ไป \" << t << \"\\n\";\n        } else {\n            std::cout << \"ยอดไม่พอ\\n\";\n        }\n    }\n    return 0;\n}\n", xp: 70,
