            goal: "input: n ตามด้วยคะแนน n ค่า · แสดง <b>คะแนนที่ปรับแล้ว: …</b> (ต่ำกว่า 0 เป็น 0 · เกิน 100 เป็น 100) และ <b>เฉลี่ย: X.XX</b>",
            starter: "// === util.h ===\n#pragma once\n\nint clampScore(int s) {\n    if (s < 0) return 0;\n    if (s > 100) return 100;\n    return s;\n}\n\n// === stats.h ===\n#pragma once\n#include <vector>\n\ndouble averageClamped(const std::vector<int>& scores);\n\n// === stats.cpp ===\n#include \"stats.h\"\n#include \"util.h\"\n\ndouble averageClamped(const std::vector<int>& scores) {\n    long long sum = 0;\n    for (int s : scores) sum += clampScore(s);\n    return static_cast<double>(sum) / static_cast<double>(scores.size());\n}\n\n// === main.cpp ===\n#include <iomanip>\n#include <iostream>\n#include <vector>\n#include \"stats.h\"\n#include \"util.h\"\n\nint main() {\n    int n;\n    std::cin >> n;\n    std::vector<int> scores(n);\n    for (int& s : scores) std::cin >> s;\n    std::cout << \"คะแนนที่ปรับแล้ว:\";\n    for (int s : scores) std::cout << \" \" << clampScore(s);\n    std::cout << \"\\n\" << std::fixed << std::setprecision(2) << \"เฉลี่ย: \" << averageClamped(scores) << \"\\n\";\n    return 0;\n}\n", xp: 60,
