            starter: "#include <algorithm>\n#include <iostream>\n#include <map>\n#include <string>\n#include <utility>\n#include <vector>\n\nstd::map<std::string, int> votes;\nint* totalVotes = new int(0);\n\nvoid castVote(std::string name) {\n    votes[name]++;\n    (*totalVotes)++;\n    std::cout << \"โหวต \" << name << \" (รวม \" << votes[name] << \")\\n\";\n}\n\nvoid printTop(int n) {\n    if (votes.empty()) { std::cout << \"ยังไม่มีการโหวต\\n\"; return; }\n    std::vector<std::pair<std::string, int>> list(votes.begin(), votes.end());\n    std::sort(list.begin(), list.end(), [](auto& a, auto& b) { return a.second != b.second ? a.second > b.second : a.first < b.first; });\n    for (int i = 0; i < n && i < (int)list.size(); i++) {\n        std::cout << i + 1 << \". \" << list[i].first << \" — \" << list[i].second << \" เสียง\\n\";\n    }\n}\n\nint main() {\n    std::string cmd;\n    while (std::cin >> cmd) {\n        if (cmd == \"vote\") { std::string name; std::cin >> name; castVote(name); }\n        else if (cmd == \"top\") { int n; std::cin >> n; printTop(n); }\n        else if (cmd == \"total\") std::cout << \"รวม \" << *totalVotes << \" เสียง จาก \" << votes.size() << \" คน\\n\";\n    }\n    delete totalVotes;\n    return 0;\n}\n", xp: 140,
